// DX-Ball service worker (generated by web/build-pwa.mjs). VERSION changes with every build (hash of index.html), so the
// browser sees a new sw.js, installs it, and the old cache is dropped on activate.
const VERSION = '7286aefa2b19';
const CACHE = 'dxball-' + VERSION;
// Only the small files are pre-cached on install, so the worker activates within seconds even on a phone. (Pre-caching
// the ~40 MB page here made install a second full download; until it finished the worker never activated, and Chrome
// on Android would not install the app.) The page itself is stored once, as index.html, after activation: every
// navigation within the scope ('./', './?x=1', './index.html') is answered with that one entry.
const SHELL = ['manifest.webmanifest', 'icon-192.png', 'icon-512.png', 'icon-maskable-512.png', 'apple-touch-icon.png'];
const SCOPE = new URL('./', self.location).href;   // e.g. https://rgoliveira.com/dxball/
const PAGE = new URL('index.html', SCOPE).href;

self.addEventListener('install', (e) => {
  // skipWaiting() is safe here: the game is one self-contained page that fetches nothing else from this scope while
  // it runs, so a new worker taking over mid-game changes nothing until the next launch.
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL.map((u) => new Request(u, { cache: 'no-cache' })))).then(() => self.skipWaiting()));
});

/** Store the page in the background. cache:'no-cache' revalidates with the server, so the copy the browser just
 *  downloaded is reused (304) instead of fetched again, and a stale copy is never stored for a new version. */
async function cachePage() {
  const cache = await caches.open(CACHE);
  if (await cache.match(PAGE)) return;
  const res = await fetch(new Request(PAGE, { cache: 'no-cache' }));
  if (res.status === 200 && res.type === 'basic') await cache.put(PAGE, res);
}

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    let replaced = false;
    for (const k of await caches.keys()) if (k.startsWith('dxball-') && k !== CACHE) { await caches.delete(k); replaced = true; }
    await self.clients.claim();
    // An update (not a first install): the open page is still the old version, served from the old cache. Tell it, so
    // it can reload (main.js: at once before play starts, else via a "new version" link on the title screen).
    if (replaced) for (const c of await self.clients.matchAll({ type: 'window' })) c.postMessage('dxball-updated');
  })());
});

// The page asks for this after its load event, so the page is never downloaded twice at the same time on a slow
// connection. (The fetch handler below also stores it on a later navigation if this did not happen.)
self.addEventListener('message', (e) => { if (e.data === 'cache-page') e.waitUntil(cachePage().catch(() => {})); });

self.addEventListener('fetch', (e) => {
  const req = e.request;
  // Only GETs inside this scope (same origin, under /dxball/); everything else goes straight to the network.
  if (req.method !== 'GET' || !req.url.startsWith(SCOPE)) return;
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const key = req.mode === 'navigate' ? PAGE : req;      // all navigations are the same single-file document
    const hit = await cache.match(key);
    if (hit) return hit;                                   // cache-first
    // On a miss, revalidate with the server (cache:'no-cache'): a plain fetch could get a copy up to 10 minutes stale from
    // the browser's HTTP cache (GitHub Pages max-age=600) and store the previous version for good.
    const res = await fetch(req.mode === 'navigate' ? new Request(PAGE, { cache: 'no-cache' }) : new Request(req, { cache: 'no-cache' }));
    // Keep a copy of successful full responses (clone() before the body is read; the original goes to the page).
    // Skip partial (206), error and opaque responses. Not awaited, so the page is not delayed by the cache write.
    if (res.status === 200 && res.type === 'basic') e.waitUntil(cache.put(key, res.clone()).catch(() => {}));
    return res;
  })());
});
